    // ---- Control flow ----

    #[test]
    fn lower_if_then_else() {
        // Simple diamond `if (cond) y = a; else y = b` lowers to Select.
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x, y
  x = 5
  if (x > 0) then
    y = 1
  else
    y = -1
  end if
end program
",
        );
        assert!(
            ir.contains("select"),
            "simple diamond should lower to select: {}",
            ir
        );
    }

    #[test]
    fn lower_if_then_else_branching() {
        // Non-diamond IF/ELSE (multi-statement body) must still use branches.
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x, y, z
  x = 5
  if (x > 0) then
    y = 1
    z = 2
  else
    y = -1
    z = -2
  end if
end program
",
        );
        assert!(
            ir.contains("cond_br"),
            "multi-stmt if/else should use branches: {}",
            ir
        );
        assert!(ir.contains("if_then"));
        assert!(ir.contains("if_else"));
        assert!(ir.contains("if_end"));
    }

    #[test]
    fn nondefault_logical_condition_lowers_to_bool() {
        let module = lower_source(
            "\
program test
  implicit none
  logical(1) :: flag
  integer :: x, y, left(2), right(2), selected(2)
  flag = .true._1
  left = [1, 2]
  right = [3, 4]
  if (flag) then
    x = 1
    y = 2
  else
    x = 3
    y = 4
  end if
  x = (flag ? 5 : 6)
  selected = (flag ? left : right)
  where (flag) y = y + 1
  if (flag) then
    x = 7
  else
    x = 8
  end if
end program
",
        );
        let ir = printer::print_module(&module);
        let mut condition_count = 0;
        let mut select_count = 0;
        for func in &module.functions {
            for block in &func.blocks {
                if let Some(crate::ir::inst::Terminator::CondBranch { cond, .. }) =
                    &block.terminator
                {
                    condition_count += 1;
                    assert_eq!(
                        func.value_type(*cond),
                        Some(IrType::Bool),
                        "conditional branch must receive Bool:\n{ir}"
                    );
                }
                for inst in &block.insts {
                    if let crate::ir::inst::InstKind::Select(cond, _, _) = &inst.kind {
                        select_count += 1;
                        assert_eq!(
                            func.value_type(*cond),
                            Some(IrType::Bool),
                            "select must receive Bool:\n{ir}"
                        );
                    }
                }
            }
        }
        assert!(
            condition_count >= 4,
            "expected all condition-lowering paths to branch:\n{ir}"
        );
        assert!(select_count > 0, "expected the IF select fast path:\n{ir}");
    }

