    #[test]
    fn generic_derived_result_does_not_inherit_renamed_character_dummy_abi() {
        let (module, ir) = lower_and_verify(include_str!(
            "../../../test_programs/generic_private_rename_derived_result.f90"
        ));
        let callee_name = "afs_modproc_generic_private_rename_string_mod_lower_string";
        let (callee_index, callee) = module
            .functions
            .iter()
            .enumerate()
            .find(|(_, function)| function.name == callee_name)
            .expect("missing selected generic specific");
        assert_eq!(
            callee.params.len(),
            2,
            "derived-result specific must use only sret plus its visible dummy",
        );
        let caller = module
            .functions
            .iter()
            .find(|function| function.name.starts_with("__prog_"))
            .expect("missing program caller");
        let call_arities: Vec<usize> = caller
            .blocks
            .iter()
            .flat_map(|block| &block.insts)
            .filter_map(|inst| match &inst.kind {
                InstKind::Call(FuncRef::External(name), args) if name == callee_name => {
                    Some(args.len())
                }
                InstKind::Call(FuncRef::Internal(index), args)
                    if *index as usize == callee_index =>
                {
                    Some(args.len())
                }
                _ => None,
            })
            .collect();
        assert!(
            !call_arities.is_empty(),
            "missing generic call to selected derived-result specific:\n{ir}",
        );
        assert!(
            call_arities
                .iter()
                .all(|arity| *arity == callee.params.len()),
            "renamed character procedure metadata leaked into derived-result calls: \
             callee has {} parameters, call arities are {call_arities:?}\n{ir}",
            callee.params.len(),
        );
    }

    #[test]
    fn host_associated_procedure_pointer_call_forwards_full_closure_abi() {
        let (module, ir) = lower_and_verify(
            "\
program p
  use iso_c_binding, only: c_funptr, c_funloc, c_f_procpointer, c_int
  implicit none
  abstract interface
    subroutine cb_i(out) bind(C)
      import :: c_int
      integer(c_int), intent(out) :: out
    end subroutine
  end interface
  procedure(cb_i), pointer :: fp
  type(c_funptr) :: raw
  integer(c_int) :: got

  raw = c_funloc(fill_answer)
  call c_f_procpointer(raw, fp)
  call wrapper(got)
contains
  subroutine wrapper(out)
    integer(c_int), intent(out) :: out
    call fp(out)
  end subroutine wrapper

  subroutine fill_answer(out) bind(C)
    integer(c_int), intent(out) :: out
    out = 42_c_int
  end subroutine fill_answer
end program p
",
        );
        let (wrapper_index, wrapper) = module
            .functions
            .iter()
            .enumerate()
            .find(|(_, function)| {
                function.name.starts_with("afs_internal___prog_p_")
                    && function.params.len() == 2 + crate::sema::type_layout::PROC_PTR_CLOSURE_SLOTS
            })
            .expect("missing contained wrapper with captured procedure pointer");
        let caller = module
            .functions
            .iter()
            .find(|function| function.name == "__prog_p")
            .expect("missing lowered program");
        let call_args = caller
            .blocks
            .iter()
            .flat_map(|block| &block.insts)
            .find_map(|inst| match &inst.kind {
                InstKind::Call(FuncRef::Internal(index), args)
                    if *index as usize == wrapper_index =>
                {
                    Some(args)
                }
                InstKind::Call(FuncRef::External(name), args) if name == &wrapper.name => {
                    Some(args)
                }
                _ => None,
            })
            .unwrap_or_else(|| panic!("missing call to captured procedure-pointer wrapper:\n{ir}"));

        assert_eq!(
            call_args.len(),
            wrapper.params.len(),
            "caller must forward the captured procedure pointer and every reserved closure slot:\n{ir}",
        );
    }

    #[test]
    fn preserves_module_owner_when_releasing_bound_character_results() {
        let (_, ir) = lower_and_verify(
            "\
module owned_bound_result_m
  implicit none
  type :: owned_factory_t
  contains
    procedure :: make_bound
  end type
contains
  function make_bound(self) result(value)
    class(owned_factory_t), intent(in) :: self
    character(:), allocatable :: value
    value = 'owned'
  end function
end module
module borrowed_bound_result_m
  implicit none
  type :: borrowed_factory_t
  contains
    procedure :: make_bound
  end type
contains
  function make_bound(self) result(value)
    class(borrowed_factory_t), intent(in) :: self
    character(:), pointer :: value
    character(8), target, save :: storage = 'borrowed'
    value => storage
  end function
end module
program p
  use owned_bound_result_m, only: owned_factory_t
  use borrowed_bound_result_m, only: borrowed_factory_t
  implicit none
  type(owned_factory_t) :: owned
  type(borrowed_factory_t) :: borrowed
  character(16) :: sink
  sink = owned%make_bound()
  sink = borrowed%make_bound()
end program
",
        );
        let program_start = ir
            .find("func @__prog_p")
            .expect("missing program function IR");
        let program_tail = &ir[program_start..];
        let program_end = program_tail
            .find("\n  func @")
            .unwrap_or(program_tail.len());
        let program_ir = &program_tail[..program_end];
        let owned_start = program_ir
            .find("call @afs_modproc_owned_bound_result_m_make_bound")
            .expect("missing owned module binding call");
        let borrowed_start = program_ir
            .find("call @afs_modproc_borrowed_bound_result_m_make_bound")
            .expect("missing borrowed module binding call");

        assert!(
            program_ir[owned_start..borrowed_start].contains("rt_call @__afs_deallocate"),
            "allocatable result from the selected module binding must be released:\n{}",
            &program_ir[owned_start..borrowed_start]
        );
        assert!(
            !program_ir[borrowed_start..].contains("rt_call @__afs_deallocate"),
            "pointer result from the same-named binding in another module must remain borrowed:\n{}",
            &program_ir[borrowed_start..]
        );
        assert_eq!(program_ir.matches("rt_call @__afs_deallocate").count(), 1);
    }

